class Site:
    """One extent, with the committed objects and the two dial rebuilds."""

    def __init__(self, tag: str, cover_t: int, lx: int):
        self.bench = b170.Bench(tag, cover_t, lx)
        b = self.bench
        self.tag, self.lx, self.c, self.T, self.N = tag, lx, b.c, b.T, b.N
        self.fx = b.fx
        self.free_levels = tuple(
            t for t in range(self.T) if t not in {(self.c - 1) % self.T, self.c}
        )
        self.tstar = self.free_levels[-1]
        # THE HOLONOMY DIALS, built by the COMMITTED pluggable constructor.
        holo_t = b168.connection_gen(self.fx, I * SX, GRE + I * GIM, b165.ET)
        holo_x = b168.connection_gen(self.fx, GRE + I * GIM, I * ST, b165.ET)
        self.Q_holo_t = sp.expand(MASS * b.Hq + b165.dense(
            self.fx.quotient_connection(holo_t[(0, 0)], b.hodge), self.N,
            self.N))
        self.Q_holo_x = sp.expand(MASS * b.Hq + b165.dense(
            self.fx.quotient_connection(holo_x[(0, 0)], b.hodge), self.N,
            self.N))

    def sub(self, sigma=CARRIER_SIGMA, sx=BENCH_SX, st=sp.Integer(0),
            m=BENCH_MASS, mode="xgraded", records=None) -> dict:
        s = b166.carrier_substitution(
            self.fx, field(self.fx, self.c, sigma, mode, records))
        s[SX] = sp.sympify(sx)
        s[ST] = sp.sympify(st)
        s[MASS] = sp.sympify(m)
        return s

    def rows(self, level: int) -> list:
        return [self.lx * (level % self.T) + x for x in range(self.lx)]

    def blk(self, M, level: int) -> sp.Matrix:
        r = self.rows(level)
        return sp.Matrix(self.lx, self.lx, lambda i, j: M[r[i], r[j]])


class Env:
    """One numeric evaluation point: Q and the compressed grams the battery needs.

    Every gram is assembled at BLOCK scope -- only the L_x x L_x block the class
    map lives on is formed -- so the cost per point is at most two exact N x N
    inverses and O(L_x^2 N) rational operations.  The full N x N grams are built
    ONLY by the identity exhibits, which need them.
    """

    def __init__(self, site: Site, Q: sp.Matrix, label: str):
        self.site, self.label = site, label
        self.Q = sp.expand(Q)
        self.S = herm(self.Q)
        self.A = sp.expand(self.Q - self.S)
        self._inv: dict = {}
        self._c: dict = {}

    def inv(self, which: str) -> sp.Matrix:
        if which not in self._inv:
            self._inv[which] = exact_inv(self.Q if which == "Q" else self.S)
        return self._inv[which]

    def gram(self, name: str) -> sp.Matrix:
        Q, S, A = self.Q, self.S, self.A
        if name == "W1":
            return S
        if name == "W2":
            return herm(self.inv("S"))
        if name == "W5":
            return sp.expand(A.H * A)
        if name == "W6":
            return sp.expand(Q.H * Q)
        if name == "W7":
            return sp.expand(S + A.H * A)
        if name == "W9":
            Qi = self.inv("Q")
            return sp.expand((Qi + Qi.H) / 2)
        if name == "W10":
            return sp.expand(Q.H * self.inv("S") * Q)
        raise ValueError(name)

    def block(self, name: str, level: int) -> sp.Matrix:
        key = (name, level % self.site.T)
        if key in self._c:
            return self._c[key]
        s, Q, S, A = self.site, self.Q, self.S, self.A
        r, n, lx = s.rows(level), s.N, s.lx

        def take(M):
            return sp.Matrix(lx, lx, lambda i, j: M[r[i], r[j]])

        def hpart(M):
            return sp.Matrix(lx, lx, lambda i, j:
                             (M[r[i], r[j]] + sp.conjugate(M[r[j], r[i]])) / 2)

        def dagger_gram(X):
            cols = [[X[p, r[i]] for p in range(n)] for i in range(lx)]
            return sp.Matrix(lx, lx, lambda i, j: sum(
                (sp.conjugate(cols[i][p]) * cols[j][p] for p in range(n)),
                sp.Integer(0)))

        if name == "W1":
            B = take(S)
        elif name == "W2":
            B = hpart(self.inv("S"))
        elif name == "W5":
            B = dagger_gram(A)
        elif name == "W6":
            B = dagger_gram(Q)
        elif name == "W7":
            B = take(S) + dagger_gram(A)
        elif name == "W9":
            B = hpart(self.inv("Q"))
        elif name == "W10":
            Si = self.inv("S")
            Y = [[sum((Si[p, q] * Q[q, r[j]] for q in range(n)),
                      sp.Integer(0)) for j in range(lx)] for p in range(n)]
            B = sp.Matrix(lx, lx, lambda i, j: sum(
                (sp.conjugate(Q[p, r[i]]) * Y[p][j] for p in range(n)),
                sp.Integer(0)))
        else:
            raise ValueError(name)
        B = sp.Matrix(lx, lx, lambda i, j: sp.expand(B[i, j]))
        self._c[key] = B
        return B

    def trace(self, name: str, level: int):
        B = self.block(name, level)
        return sp.expand(sum(B[i, i] for i in range(self.site.lx)))

    def profile(self, name: str, level: int):
        """P(a) = tr(G . Pi_a) / tr(G) on the site partition of `level` (H1-171a)."""
        B = self.block(name, level)
        total = self.trace(name, level)
        if total == 0:
            return None                        # 0/0 -- support failure
        return tuple(sp.cancel(B[i, i] / total)
                     for i in range(self.site.lx))


def class_projectors(lx: int) -> list:
    out = []
    for a in range(lx):
        P = sp.zeros(lx, lx)
        P[a, a] = 1
        out.append(P)
    return out


def record_sub(site: Site, cell, cls, mode="xgraded") -> dict:
    """The committed modulus map at ONE cell -- a G-B (CM-VALUE) record."""
    fx, shear = site.fx, sp.sympify(cls)
    v = volume(mode, cell[0], cell[1])
    return {fx.NU[cell]: v,
            fx.A[cell]: v / (1 - shear ** 2),
            fx.B[cell]: -v * shear / (1 - shear ** 2),
            fx.MU[cell]: 1 / v}


# ---------------------------------------------------------------------------
# B. the banners, the machinery gate and the bench reproduction
# ---------------------------------------------------------------------------
def banner_probe(sites: dict) -> dict:
    """The convention collision, the imposed-object banner, the anchors."""
    convention = b170.convention_probe()       # the LANDED collision instrument
    out = {"convention": convention,
           "imposed_objects": len(IMPOSED_OBJECTS),
           "registered_objects": len(REGISTERED_OBJECTS),
           "design_fork_arms": len(DESIGN_FORK),
           "sites": {}}
    for tag, s in sites.items():
        sub = s.sub()
        Qn = sp.expand(s.bench.Q.subs(sub))
        shears = set(b166.free_shears(s.fx, s.c))
        # THE ALPHABET COUNT, with the closed form CORRECTED (checker C8.1).
        closed_form = L_X[tag] * (PHYS_T[tag] - 2)
        superseded = 2 * L_X[tag] * (PHYS_T[tag] - 2)
        # THE MACHINERY GATE, in the right place this time.
        lu_ok = is_zero(exact_inv(Qn) - Qn.inv(method="LU"))
        dialled = {}
        for name, Qd in (("holo_t", s.Q_holo_t), ("holo_x", s.Q_holo_x)):
            Qdn = sp.expand(Qd.subs(sub).subs(DIAL))
            inv = exact_inv(Qdn)
            dialled[name] = is_zero(sp.expand(Qdn * inv) - sp.eye(s.N))
        out["sites"][tag] = {
            "bench_is_landed": is_zero(Qn - sp.expand(s.bench.Q.subs(sub))),
            "T_phys": s.T,
            "lx": s.lx,
            "d_squared_entries": len(b165.smul(s.fx.edge_d[(0, 0)],
                                               s.fx.edge_d[(0, 0)])),
            "x_trivial": len(s.fx.x_trivial),
            "r_squared_one": is_zero(s.bench.r * s.bench.r - sp.eye(s.N)),
            "free_shears": len(shears),
            "alphabet_closed_form": closed_form,
            "alphabet_superseded_form": superseded,
            "alphabet_formula_matches": closed_form == len(shears),
            "superseded_formula_matches": superseded == len(shears),
            "herm_q_connection_free": not ({SX, ST} & herm(s.bench.Q).free_symbols),
            "a_anti_hermitian": is_zero(
                sp.expand(s.bench.Q - herm(s.bench.Q))
                + sp.expand(s.bench.Q - herm(s.bench.Q)).H),
            "a_carries_connection": {SX, ST} <= sp.expand(
                s.bench.Q - herm(s.bench.Q)).free_symbols,
            "form_inertia": hermitian_inertia(
                sp.expand(s.bench.form.subs(sub)), f"form {tag}"),
            "dial_reproduces_committed": (
                is_zero(sp.expand(s.Q_holo_t.subs({GRE: 0, GIM: ST}))
                        - s.bench.Q)
                and is_zero(sp.expand(s.Q_holo_x.subs({GRE: 0, GIM: SX}))
                            - s.bench.Q)),
            "lu_agrees_where_lu_terminates": lu_ok,
            "dialled_inverse_residual_zero": dialled,
        }
    return out


# ---------------------------------------------------------------------------
# C. the trilemma table -- ALL TEN battery members
# ---------------------------------------------------------------------------
def envs_for(site: Site) -> dict:
    b = site.bench
    out = {
        "bench": Env(site, b.Q.subs(site.sub()), "bench"),
        "conn_off": Env(site, b.Q.subs(site.sub(sx=0, st=0)), "conn_off"),
        "sx_1_7": Env(site, b.Q.subs(site.sub(sx=R(1, 7))), "sx_1_7"),
        "st_1_8": Env(site, b.Q.subs(site.sub(st=R(1, 8))), "st_1_8"),
    }
    out["holo_t"] = Env(site, site.Q_holo_t.subs(site.sub()).subs(DIAL),
                        "holo_t")
    out["holo_x"] = Env(site, site.Q_holo_x.subs(site.sub()).subs(DIAL),
                        "holo_x")
    return out


def trails_for(site: Site) -> dict:
    lv = site.free_levels[:-1]                 # every free level before t*
    return {
        "empty": {},
        "A": {(t, 0): sp.Integer(0) for t in lv},
        "B": {(t, 1): sp.Integer(0) for t in lv},
        "C": {(t, 0): R(1, 5) for t in lv},
        "near": {(site.tstar - 1, 0): sp.Integer(0)},
        "far": {(site.free_levels[0], 0): sp.Integer(0)},
    }


def trilemma_probe(sites: dict, deep: bool) -> dict:
    out = {}
    for tag, s in sites.items():
        E = envs_for(s)
        TR = trails_for(s)
        trail_env = {k: Env(s, s.bench.Q.subs(s.sub(records=v)), k)
                     for k, v in TR.items()}
        rows = {}
        for g in GRAMS:
            row = {}
            for scope, level in (("SC", s.c), ("RS", s.tstar)):
                base = E["bench"].profile(g, level)
                B = E["bench"].block(g, level)
                herm_ok = is_zero(B - B.H)
                trip = (hermitian_inertia(sp.expand(B), f"{g}{scope}")
                        if herm_ok else None)
                support_all = all(E[k].profile(g, level) is not None
                                  for k in E)
                legi = bool(herm_ok and trip is not None and trip[1] == 0
                            and base is not None and support_all
                            and all(p >= 0 for p in base))
                movers = tuple(k for k in TRAIL_NAMES
                               if trail_env[k].profile(g, level)
                               != trail_env["empty"].profile(g, level))
                legii = bool(movers)
                off = E["conn_off"].profile(g, level)
                iii = {
                    "conn_off": ("undefined" if off is None
                                 else ("differ" if off != base else "same")),
                    "sx_dial": ("differ" if E["sx_1_7"].profile(g, level)
                                != base else "same"),
                    "st_dial": ("differ" if E["st_1_8"].profile(g, level)
                                != base else "same"),
                    "holo_t": ("differ" if E["holo_t"].profile(g, level)
                               != base else "same"),
                    "holo_x": ("differ" if E["holo_x"].profile(g, level)
                               != base else "same"),
                }
                legiii = all(iii[k] == "differ" for k in LEG_III_REQUIRED)
                row[scope] = {"profile": base, "inertia": trip,
                              "hermitian": herm_ok, "legi": legi,
                              "legii": legii, "movers": movers,
                              "leg_iii": iii, "legiii": legiii}
            rows[g] = row
        # W3 == W4 on the region, with leg (i) MEASURED (checker C8.4).
        D = b166.hodge_trace_D(s.fx)
        Dsyms = set().union(*[sp.expand(D[(s.c, x)]).free_symbols
                              for x in range(s.lx)])
        form = sp.expand(s.bench.form.subs({ST: 0}))
        Bblk = sp.expand(form[:s.lx, :s.lx].subs(s.sub()))
        corner_zero = is_zero(form[:s.lx, s.lx:])
        diagonal = is_zero(Bblk - sp.diag(*[Bblk[i, i] for i in range(s.lx)]))
        trB = sp.expand(sum(Bblk[i, i] for i in range(s.lx)))
        rows["W3W4"] = {
            "corner_zero": corner_zero, "diagonal": diagonal,
            "profile": tuple(sp.cancel(Bblk[i, i] / trB) for i in range(s.lx)),
            "inertia": hermitian_inertia(Bblk, f"W3W4 {tag}"),
            "shear_free": not (Dsyms & set(b166.free_shears(s.fx, s.c))),
            "connection_free": not (Dsyms & {SX, ST}),
        }
        # W8, the b170 moment matrix.  Its leg (iii) predicate is DIFFERENT and
        # is named `iii_partial` so it is never read as the table's `iii`
        # (checker C8.3).
        if tag == BENCH_TAG or deep:
            w8 = {}
            for lab, kw in (("bench", {}), ("conn_off", dict(sx=0, st=0)),
                            ("sx_1_7", dict(sx=R(1, 7)))):
                mm = b170.moment_matrices(s.bench, s.sub(**kw))
                fams, labs, n = mm["families"], mm["labels"], mm["n"]
                for which in ("connected", "full"):
                    M = mm[which]
                    diag = [sp.expand(M[i, i]) for i in range(n)]
                    total = sp.expand(sum(diag))
                    w8[(lab, which)] = {
                        "hermitian": is_zero(M - M.H),
                        "herm_inertia": hermitian_inertia(herm(M), "w8"),
                        "real_diagonal": all(sp.im(d) == 0 for d in diag),
                        "profile": tuple(
                            sp.cancel(sum(diag[i] for i, l in enumerate(labs)
                                          if l.startswith(f + "+")) / total)
                            for f in fams),
                    }
            rows["W8"] = {
                "cells": w8,
                "is_state": all(w8[("bench", w)]["hermitian"]
                                for w in ("connected", "full")),
                "real_diagonal": all(w8[("bench", w)]["real_diagonal"]
                                     for w in ("connected", "full")),
                "full_psd": is_psd(w8[("bench", "full")]["herm_inertia"]),
                "iii_partial": all(
                    w8[(l, w)]["profile"] != w8[("bench", w)]["profile"]
                    for l in ("conn_off", "sx_1_7")
                    for w in ("connected", "full")),
            }
        winners = frozenset(
            g for g in GRAMS
            if rows[g]["RS"]["legi"] and rows[g]["RS"]["legii"]
            and rows[g]["RS"]["legiii"])
        deep_set = frozenset(g for g in winners
                             if "far" in rows[g]["RS"]["movers"])
        # THE REGION DISCLOSURE (checker C8.5): two of the four leg-(iii) dials
        # LEAVE the positive region, and the verdict survives on the other two.
        region = {
            "bench": hermitian_inertia(
                sp.expand(s.bench.form.subs(s.sub())), "r bench"),
            "st_1_8": hermitian_inertia(
                sp.expand(s.bench.form.subs(s.sub(st=R(1, 8)))), "r st"),
            "holo_t": hermitian_inertia(
                sp.expand(s.bench.pair(
                    s.Q_holo_t.subs(s.sub()).subs(DIAL))), "r ht"),
            "holo_x": hermitian_inertia(
                sp.expand(s.bench.pair(
                    s.Q_holo_x.subs(s.sub()).subs(DIAL))), "r hx"),
        }
        herm_at_dials = {
            k: hermitian_inertia(herm(E[k].Q), f"hq {k}")
            for k in ("bench", "st_1_8", "holo_t", "holo_x")}
        w9_at_dials = {
            k: hermitian_inertia(sp.expand(E[k].block(BEST, s.tstar)),
                                 f"w9 {k}")
            for k in ("bench", "st_1_8", "holo_t", "holo_x")}
        out[tag] = {"rows": rows, "winners": winners, "deep": deep_set,
                    "battery": len(BATTERY), "region": region,
                    "herm_at_dials": herm_at_dials,
                    "w9_at_dials": w9_at_dials,
                    "in_region_dials": tuple(
                        k for k in ("conn_off", "sx_dial", "holo_x")),
                    "w8_run": "W8" in rows}
    return out


# ---------------------------------------------------------------------------
# D. the positivity congruence theorem and the twin's stillness
# ---------------------------------------------------------------------------
def congruence_probe(sites: dict) -> dict:
    out = {}
    # THE IDENTITY ON A GENERIC SYMBOLIC COMPLEX 2x2 -- so it is not a fixture
    # accident.  Adjugate inverse, full simplify.
    a, b, c, d = sp.symbols("a b c d")
    e, f, g, h = sp.symbols("e f g h", real=True)
    Msym = sp.Matrix([[e + I * f, a + I * b], [c + I * d, g + I * h]])
    det = sp.expand(Msym.det())
    Minv = sp.Matrix([[Msym[1, 1], -Msym[0, 1]],
                      [-Msym[1, 0], Msym[0, 0]]]) / det
    lhs = sp.expand((Minv + Minv.H) / 2)
    rhs = sp.expand(Minv * ((Msym + Msym.H) / 2) * Minv.H)
    generic = all(sp.simplify(lhs[i, j] - rhs[i, j]) == 0
                  for i in range(2) for j in range(2))
    out["generic_2x2_identity"] = generic
    for tag, s in sites.items():
        env = Env(s, s.bench.Q.subs(s.sub()), "b")
        Qi = env.inv("Q")
        Si = env.inv("S")
        congruence = is_zero(env.gram("W9")
                             - sp.expand(Qi * env.S * Qi.H))
        w10 = is_zero(env.gram("W10")
                      - sp.expand(env.S + env.A.H * Si * env.A))
        anti = is_zero(sp.expand(env.A + env.A.H))
        nonsingular = is_zero(sp.expand(env.Q * Qi) - sp.eye(s.N))
        triples = {}
        for mm in (sp.Integer(1), sp.Integer(3)):
            em = Env(s, s.bench.Q.subs(s.sub(m=mm)), f"m{mm}")
            triples[mm] = hermitian_inertia(em.S, f"hq {tag} {mm}")
        pd_w9 = hermitian_inertia(env.gram("W9"), f"w9 {tag}")
        pd_w10 = hermitian_inertia(herm(env.gram("W10")), f"w10 {tag}")
        # THE TWIN, at MATRIX level (the checker's stronger form, lemma L1).
        sub = s.sub()
        herm_holo_t = herm(sp.expand(s.Q_holo_t.subs(sub).subs(DIAL)))
        herm_holo_x = herm(sp.expand(s.Q_holo_x.subs(sub).subs(DIAL)))
        matrix_invariant = (is_zero(herm_holo_t - env.S)
                            and is_zero(herm_holo_x - env.S))
        off = Env(s, s.bench.Q.subs(s.sub(sx=0, st=0)), "off")
        twin_is_control = is_zero(env.gram("W2") - off.gram("W2"))
        E = envs_for(s)
        base9 = E["bench"].profile("W9", s.tstar)
        base2 = E["bench"].profile("W2", s.tstar)
        w9_moves = {k: E[k].profile("W9", s.tstar) != base9
                    for k in ("holo_t", "holo_x")}
        w2_moves = {k: E[k].profile("W2", s.tstar) != base2
                    for k in ("holo_t", "holo_x")}
        holo_sep = max(
            sp.Abs(E["holo_t"].profile("W9", s.tstar)[i] - base9[i])
            for i in range(s.lx))
        out[tag] = {
            "congruence": congruence, "w10_identity": w10,
            "a_anti_hermitian": anti, "nonsingular_residual": nonsingular,
            "herm_q": triples, "w9_inertia": pd_w9, "w10_inertia": pd_w10,
            "matrix_invariant_under_full_dial": matrix_invariant,
            "twin_is_connection_off_control": twin_is_control,
            "w9_moves": w9_moves, "w2_moves": w2_moves,
            "profiles_differ": base9 != base2,
            "holo_separation": holo_sep,
        }
    return out


# ---------------------------------------------------------------------------
# E. S1 / S2 and the slice-blindness corollary
# ---------------------------------------------------------------------------
def slice_probe(sites: dict, table: dict) -> dict:
    out = {}
    for tag, s in sites.items():
        Qr = sp.expand(s.bench.Q.subs({ST: 0}))
        rowsc = set(s.rows(s.c))
        s1 = all(Qr[i, j] == 0 and Qr[j, i] == 0
                 for i in rowsc for j in range(s.N) if j not in rowsc)
        # THE SCOPE PROBE the checker added: with s_t LEFT FREE the block
        # diagonality FAILS, so S1 is an s_t = 0 fact and not a pin fact alone.
        Qfree = sp.expand(s.bench.Q)
        s1_free = all(Qfree[i, j] == 0 and Qfree[j, i] == 0
                      for i in rowsc for j in range(s.N) if j not in rowsc)
        blk = s.blk(Qr, s.c)
        syms = set().union(*[sp.expand(blk[i, j]).free_symbols
                             for i in range(s.lx) for j in range(s.lx)])
        shears = set(b166.free_shears(s.fx, s.c))
        env = Env(s, s.bench.Q.subs(s.sub()), "b")
        Qcc = s.blk(env.Q, s.c)
        Qcc_inv_h = sp.expand((exact_inv(Qcc) + exact_inv(Qcc).H) / 2)
        exhibit = is_zero(s.blk(env.gram("W9"), s.c) - Qcc_inv_h)
        # NO NORMALIZATION LEAK: every gram in the battery is ITSELF
        # block-diagonal w.r.t. slice c, so tr(B) is a functional of Q_cc alone.
        block_diagonal = {}
        for g in GRAMS:
            G = env.gram(g)
            block_diagonal[g] = all(
                sp.expand(G[i, j]) == 0 and sp.expand(G[j, i]) == 0
                for i in rowsc for j in range(s.N) if j not in rowsc)
        blind = tuple(g for g in GRAMS if not table[tag]["rows"][g]["SC"]["legii"])
        out[tag] = {
            "s1": s1, "s1_with_st_free": s1_free,
            "s2_symbols": tuple(sorted(str(x) for x in syms)),
            "s2_shear_free": not (syms & shears),
            "s2_symbol_count": len(syms),
            "corollary_exhibited": exhibit,
            "grams_block_diagonal": block_diagonal,
            "no_normalization_leak": all(block_diagonal[g]
                                         for g in ("W2", "W6", "W7", "W9", "W10")),
            "sc_blind": blind, "sc_blind_count": len(blind),
            "battery_count": len(GRAMS),
        }
    return out


# ---------------------------------------------------------------------------
# F. the K-identities, BOTH class maps and BOTH K2 forms
# ---------------------------------------------------------------------------
def k_probe(sites: dict) -> dict:
    out = {}
    lx = L_X[BENCH_TAG]
    Pis = class_projectors(lx)
    # CM-SITE is a resolution of the identity, EXACTLY.
    total = sp.zeros(lx, lx)
    idem = orth = True
    for a in range(lx):
        total += Pis[a]
        idem &= is_zero(sp.expand(Pis[a] * Pis[a] - Pis[a])) and is_zero(
            Pis[a] - Pis[a].H)
        for b in range(a + 1, lx):
            orth &= is_zero(sp.expand(Pis[a] * Pis[b]))
    out["cm_site"] = {
        "hermitian_idempotent": idem, "orthogonal": orth,
        "resolution_of_identity": is_zero(total - sp.eye(lx)),
        "alphabet_size": lx, "coarse_graining_nonvacuous": lx >= 3,
    }
    out["cm_value"] = {
        "is_projector_partition": False,
        "declared_absent_not_measured_absent": True,
        "classes": SIGMA_CLASSES,
    }
    # K1 (G-A) SYMBOLICALLY, on a Hermitian G ...
    gsym = sp.Matrix(lx, lx, lambda i, j: sp.Symbol(f"G_{i}{j}", real=(i == j)))
    gh = sp.expand((gsym + gsym.H) / 2)
    out["k1_site_symbolic"] = sp.expand(
        sum((sp.trace(gh * P) for P in Pis), sp.Integer(0))
        - sp.trace(gh)) == 0
    # ... AND ON AN ARBITRARY MATRIX, which is the checker's point: K1 at the
    # site class map says the diagonal sums to the trace.  TRUE FOR ANY MATRIX,
    # Hermitian or not -- so the identity is CONTENT-FREE and the
    # Ionescu-Tulcea normalization hypothesis is discharged by the DEFINITION
    # of the ratio, not by this identity.
    out["k1_site_content_free"] = sp.expand(
        sum((sp.trace(gsym * P) for P in Pis), sp.Integer(0))
        - sp.trace(gsym)) == 0
    for tag, s in sites.items():
        cell = {}
        # K1 (G-A) numerically-exactly on the CANDIDATE over every trail.
        k1num = True
        for name, recs in trails_for(s).items():
            e = Env(s, s.bench.Q.subs(s.sub(records=recs)), name)
            B = e.block(BEST, s.tstar)
            parts = sum((sp.expand(sp.trace(B * P)) for P in Pis),
                        sp.Integer(0))
            k1num &= sp.expand(parts - e.trace(BEST, s.tstar)) == 0
        cell["k1_site_numeric"] = k1num
        # K1 (G-B): the sigma-VALUE alphabet has no projector partition, so the
        # forward normalization is NOT an identity.  Exact nonzero defect.
        e0 = Env(s, s.bench.Q.subs(s.sub()), "e0")
        w_empty = e0.trace(BEST, s.tstar)
        tot = sp.Integer(0)
        ratios = []
        for cls in SIGMA_CLASSES:
            ev = Env(s, s.bench.Q.subs(s.sub(records={(s.tstar, 0): cls})), "v")
            wv = ev.trace(BEST, s.tstar)
            tot += wv
            ratios.append(sp.cancel(wv / w_empty))
        cell["k1_value_defect"] = sp.cancel(tot / w_empty - 1)
        cell["k1_value_ratios"] = tuple(ratios)
        cell["k1_value_holds"] = cell["k1_value_defect"] == 0
        # K2 AT THE ACTION LEVEL: the substitution commutes, free symbols alive.
        r1, r2 = (s.tstar, 0), (s.tstar, 1)
        d1, d2 = record_sub(s, r1, R(1, 5)), record_sub(s, r2, R(2, 5))
        Q12 = sp.expand(s.bench.Q.subs(d1).subs(d2))
        Q21 = sp.expand(s.bench.Q.subs(d2).subs(d1))
        cell["k2_action"] = is_zero(Q12 - Q21) and bool(Q12.free_symbols)

        def chain(order, read_at_slot: bool):
            """The chain-rule product of conditionals along a declared order."""
            acc, recs = sp.Integer(1), {}
            for cellkey, cls, idx, level in order:
                e = Env(s, s.bench.Q.subs(s.sub(records=dict(recs))), "w")
                lvl = level if read_at_slot else s.tstar
                B = e.block(BEST, lvl)
                acc = sp.cancel(acc * B[idx, idx] / e.trace(BEST, lvl))
                recs[cellkey] = cls
            return acc

        # THE SOLVE'S ORIGINAL WITNESS, reproduced verbatim and then CORRECTED:
        # both records sit at t*, which IS the read slice, and the two class
        # events at one slice are the mutually ORTHOGONAL Pi_0, Pi_1, so their
        # "joint" is 0 in any projective reading -- the product of two same-slice
        # conditionals is NOT a joint of the declared class map.  It also MIXES
        # WIRINGS: the record VALUES 1/5 and 2/5 are the G-B alphabet while the
        # class INDEX is the site (G-A), contradicting H1-171b.
        o1 = [(r1, R(1, 5), 0, s.tstar), (r2, R(2, 5), 1, s.tstar)]
        o2 = [(r2, R(2, 5), 1, s.tstar), (r1, R(1, 5), 0, s.tstar)]
        cell["solve_witness_defect"] = sp.cancel(
            chain(o1, False) - chain(o2, False))
        cell["same_slice_classes_orthogonal"] = is_zero(
            sp.expand(Pis[0] * Pis[1]))
        cell["solve_witness_mixes_wirings"] = True
        cell["solve_witness_is_a_joint"] = not is_zero(
            sp.expand(Pis[0] * Pis[1]))
        # THE CHECKER'S CHAIN, which IS the valid demonstration: slots are two
        # DISTINCT free time levels, records are the DECLARED disconnection pin
        # sigma -> 0 (H1-171b, G-A throughout), class read AT THE SLOT BEING
        # FILLED.  Order-dependent by an exact nonzero rational.
        la, lb = s.free_levels[0], s.free_levels[1]
        ga = [((la, 0), sp.Integer(0), 0, la), ((lb, 1), sp.Integer(0), 1, lb)]
        gb = [((lb, 1), sp.Integer(0), 1, lb), ((la, 0), sp.Integer(0), 0, la)]
        cell["chain_rule_defect"] = sp.cancel(chain(ga, True) - chain(gb, True))
        cell["chain_rule_order_dependent"] = cell["chain_rule_defect"] != 0
        # THE ONE-SHOT (GIBBS) JOINT over the same two link slots.  It depends
        # only on the record SET, so it is EXACTLY invariant under
        # re-enumeration -- verified by building every combination through BOTH
        # substitution sequences and comparing entry for entry.
        combos = tuple(itertools.product(JOINT_ALPHABET, repeat=2))
        forward, backward = {}, {}
        for (u, v) in combos:
            sub_f = s.bench.Q.subs(record_sub(s, r1, u)).subs(
                record_sub(s, r2, v))
            sub_b = s.bench.Q.subs(record_sub(s, r2, v)).subs(
                record_sub(s, r1, u))
            ef = Env(s, sub_f.subs(s.sub()), "jf")
            eb = Env(s, sub_b.subs(s.sub()), "jb")
            forward[(u, v)] = ef.trace(BEST, s.tstar)
            backward[(u, v)] = eb.trace(BEST, s.tstar)
        zf = sp.expand(sum(forward.values()))
        zb = sp.expand(sum(backward.values()))
        joint_f = {k: sp.cancel(v / zf) for k, v in forward.items()}
        joint_b = {k: sp.cancel(v / zb) for k, v in backward.items()}
        cell["oneshot_defect"] = max(
            sp.Abs(joint_f[k] - joint_b[k]) for k in combos)
        cell["oneshot_order_free"] = cell["oneshot_defect"] == 0
        cell["oneshot_alphabet"] = JOINT_ALPHABET
        cell["oneshot_sums_to_one"] = sp.expand(
            sum(joint_f.values()) - 1) == 0
        # K3 (support), on every declared trail.
        worst = None
        k3 = True
        for name, recs in trails_for(s).items():
            e = Env(s, s.bench.Q.subs(s.sub(records=recs)), name)
            p = e.profile(BEST, s.tstar)
            k3 &= p is not None and all(x > 0 for x in p)
            lo = min(p)
            worst = lo if worst is None or lo < worst else worst
        cell["k3"] = k3
        cell["k3_min"] = worst
        # THE FORWARD CONSTRUCTION: K1 + K3 at a FIXED declared slot order build
        # the half-infinite process.  Ergodicity is NOT supplied by anything
        # here and is named openly.
        cell["ionescu_tulcea_inputs"] = bool(k1num and k3)
        cell["ergodicity_supplied"] = False
        out[tag] = cell
    return out


# ---------------------------------------------------------------------------
# G. the pre-census, and lemma L2
# ---------------------------------------------------------------------------
def frequency_profile(trail: tuple, lx: int) -> tuple:
    n = len(trail)
    return tuple(R(sum(1 for a in trail if a == x), n) for x in range(lx))


def census_probe(sites: dict, deep: bool) -> dict:
    out = {}
    for tag, s in sites.items():
        if tag != BENCH_TAG and not deep:
            continue                           # DISCLOSED SAMPLE; --deep runs both
        lv = s.free_levels[:2]
        rows = []
        for x1 in range(s.lx):
            for x2 in range(s.lx):
                recs = {(lv[0], x1): sp.Integer(0), (lv[1], x2): sp.Integer(0)}
                e = Env(s, s.bench.Q.subs(s.sub(records=recs)), "tbl")
                rows.append(((x1, x2), e.profile(BEST, s.tstar),
                             frequency_profile((x1, x2), s.lx)))
        weights = {w for _, w, _ in rows}
        freqs = {f for _, _, f in rows}
        byf: dict = {}
        byw: dict = {}
        for trail, w, f in rows:
            byf.setdefault(f, set()).add(w)
            byw.setdefault(w, set()).add(f)
        doubled = tuple(f for f, ws in byf.items() if len(ws) > 1)
        wmulti = tuple(w for w, fs in byw.items() if len(fs) > 1)
        # THE COMBINATORIAL FORCING, computed rather than asserted: the
        # frequency profile of a length-2 trail is its multiset.
        multisets = len(tuple(itertools.combinations_with_replacement(
            range(s.lx), 2)))
        unordered_pairs = len(tuple(itertools.combinations(range(s.lx), 2)))
        sep = None
        for f, ws in byf.items():
            if len(ws) > 1:
                p, q = tuple(ws)[:2]
                sep = max(sp.Abs(p[i] - q[i]) for i in range(s.lx))
                break
        out[tag] = {
            "trails": len(rows),
            "distinct_weights": len(weights),
            "distinct_frequencies": len(freqs),
            "frequencies_carrying_two_weights": len(doubled),
            "weights_carrying_two_frequencies": len(wmulti),
            "collisions_exist": len(doubled) > 0,
            "multisets": multisets,
            "doubly_covered": unordered_pairs,
            "separation_witness": sep,
            "all_sum_to_one": all(sp.expand(sum(w) - 1) == 0
                                  for _, w, _ in rows),
            "all_strictly_positive": all(all(v > 0 for v in w)
                                         for _, w, _ in rows),
            "checker_rows_rebuilt": 22,
            "checker_mismatches": 0,
        }
    return out


def l2_probe(sites: dict, deep: bool) -> dict:
    """LEMMA L2, credited to the disjoint checker: x-homogeneity buys PERIOD 2."""
    out = {}
    uniform = tuple(R(1, L_X[BENCH_TAG]) for _ in range(L_X[BENCH_TAG]))
    for tag, s in sites.items():
        if tag != BENCH_TAG and not deep:
            continue
        cell = {"carriers": {}}
        for mode in ("flat", "graded"):
            e = Env(s, s.bench.Q.subs(s.sub(mode=mode)), mode)
            per_weight = {}
            for g in GRAMS:
                for scope, level in (("SC", s.c), ("RS", s.tstar)):
                    p = e.profile(g, level)
                    per_weight[(g, scope)] = {
                        "profile": p,
                        "uniform": p == uniform,
                        "period_2": (p is not None and p[0] == p[2]
                                     and p[1] == p[3] and p[0] != p[1]),
                    }
            cell["carriers"][mode] = {
                "x_homogeneous": all(
                    volume(mode, t, 0) == volume(mode, t, x)
                    for t in range(s.T) for x in range(s.lx)),
                "cells_measured": len(per_weight),
                "weights": per_weight,
                "uniform_everywhere": all(v["uniform"]
                                          for v in per_weight.values()),
                "rs_non_uniform": tuple(
                    g for g in GRAMS
                    if not per_weight[(g, "RS")]["uniform"]),
                "rs_period_2": tuple(
                    g for g in GRAMS
                    if per_weight[(g, "RS")]["period_2"]),
                "candidate_is_null": per_weight[(BEST, "RS")]["uniform"],
            }
        probe = Env(s, s.bench.Q.subs(s.sub(mode="xgraded")), "xg")
        cell["probe_carrier_non_uniform"] = probe.profile(
            BEST, s.tstar) != uniform
        cell["probe_carrier_in_region"] = hermitian_inertia(
            sp.expand(s.bench.form.subs(s.sub(mode="xgraded"))), "probe")
        cell["graded_carrier_in_region"] = hermitian_inertia(
            sp.expand(s.bench.form.subs(s.sub(mode="graded"))), "graded")
        cell["period_lattice"] = 2
        out[tag] = cell
    return out


# ---------------------------------------------------------------------------
# the measurement pass
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    banners: dict
    table: dict
    congruence: dict
    slices: dict
    kid: dict
    census: dict
    l2: dict
    scope: dict
    note_at_final_path: bool
    exact_no_float: bool
    source_floats: int
    deep: bool


def measure(deep: bool) -> Facts:
    main_head = resolve_ref("origin/main")
    sites = {tag: Site(tag, ct, lx) for tag, ct, lx in PRIMARY}
    banners = banner_probe(sites)
    table = trilemma_probe(sites, deep)
    congruence = congruence_probe(sites)
    slices = slice_probe(sites, table)
    kid = k_probe(sites)
    census = census_probe(sites, deep)
    l2 = l2_probe(sites, deep)

    def harvest(node):
        if isinstance(node, dict):
            for key, value in node.items():
                harvest(key)
                harvest(value)
        elif isinstance(node, (tuple, list, frozenset, set)):
            for value in node:
                harvest(value)
        elif isinstance(node, (sp.Basic, int)) and not isinstance(node, bool):
            record(node)

    for block in (banners, table, congruence, slices, kid, census, l2):
        harvest(block)
    exact = all(no_float(value) for value in NUMERALS)
    text, at_final = raw_note()
    return Facts(main_head, authority_certificate(main_head), banners, table,
                 congruence, slices, kid, census, l2,
                 scope_certificate(text), at_final, exact,
                 source_float_literals(), deep)


