# ---------------------------------------------------------------------------
# claims: the only thing a mutation is allowed to touch
# ---------------------------------------------------------------------------
def build_claims(mutation: str) -> dict:
    claims: dict = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "lane_conventions_uniform": False,
        "winning_set": EXPECTED_WINNERS,
        "congruence_theorem": True,
        "twin_moves": False,
        "slice_weights_record_sensitive": False,
        "solve_witness_is_a_joint": False,
        "k1_value_alphabet_holds": False,
        "oneshot_order_dependent": False,
        "zero_collisions_reachable": False,
        "null_fixture_universal": False,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "claim_convention_uniform":
        # THE BANNER DENIED: the lane asserted to carry ONE inertia convention,
        # which the two-helper comparison on identical matrices forbids.
        claims["lane_conventions_uniform"] = True
    elif mutation == "claim_winning_set_wider":
        # THE ENUMERATION'S VERDICT WIDENED: W5 asserted into the winning set,
        # which its undefined connection-off ratio and s_x homogeneity forbid.
        claims["winning_set"] = EXPECTED_WINNERS | {"W5"}
    elif mutation == "break_congruence_theorem":
        # THE POSITIVITY THEOREM DENIED: herm(Q^{-1}) asserted NOT to be the
        # congruence Q^{-1} herm(Q) Q^{-dagger}, which the entry-for-entry
        # identity at both extents and the generic 2x2 derivation forbid.
        claims["congruence_theorem"] = False
    elif mutation == "claim_twin_moves":
        # THE ANTI-SHIM SEPARATION DENIED: the twin herm(Q)^{-1} asserted to
        # move under the holonomy dials, which the MATRIX-level invariance of
        # herm(Q) under the full complex dial forbids.
        claims["twin_moves"] = True
    elif mutation == "claim_slice_weights_record_sensitive":
        # S1/S2 DENIED: a slice-compressed weight asserted record-sensitive,
        # which the direct-summand theorem and the 7-of-7 measurement forbid.
        claims["slice_weights_record_sensitive"] = True
    elif mutation == "claim_k2_weight_level":
        # THE SOLVE'S ORIGINAL, MIS-WIRED READING RE-ASSERTED: the two
        # same-slice conditionals asserted to be a joint of the declared class
        # map, which Pi_0 Pi_1 = 0 forbids.
        claims["solve_witness_is_a_joint"] = True
    elif mutation == "claim_k1_value_alphabet_holds":
        # K1 ASSERTED AT THE VALUE ALPHABET, which the exact nonzero defect at
        # both extents forbids.
        claims["k1_value_alphabet_holds"] = True
    elif mutation == "claim_oneshot_order_dependent":
        # THE RESHAPED PREMISE DENIED: the one-shot Gibbs joint asserted
        # order-dependent, which its exact zero defect at both extents forbids.
        claims["oneshot_order_dependent"] = True
    elif mutation == "claim_zero_collisions_reachable":
        # THE CENSUS DESIGN RESULT DENIED: the zero-collision branch asserted
        # reachable on the site alphabet, which the 6 doubled frequency
        # profiles and the multiset argument forbid.
        claims["zero_collisions_reachable"] = True
    elif mutation == "claim_null_fixture_universal":
        # THE REFUTED SENTENCE RE-ASSERTED: every site profile asserted exactly
        # uniform on the x-homogeneous carriers for every construction in the
        # battery, which the non-uniform period-2 RS profiles of W5, W6 and W7
        # forbid.
        claims["null_fixture_universal"] = True
    elif mutation == "drop_design_fork":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS
            if key not in ("design_fork", "slot_order_fork_is_a_design_input"))
    elif mutation == "drop_cycle913":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key not in CAUTION_KEYS)
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim")
    return claims


# ---------------------------------------------------------------------------
# gates: pure functions of the measured facts and the claims
# ---------------------------------------------------------------------------
def evaluate_gates(facts: Facts, claims: dict, elapsed_ns: int) -> dict:
    authority = facts.authority
    parent_blobs_ok = (authority.parent_artifact_blobs
                       if claims["parent_pin"] == "resolved"
                       else authority.stale_parent_artifact_blobs)
    gate_a = bool(
        AUDIT_INPUT_PATHS == (
            "docs/ADMISSIBILITY_DIRAC_KAHLER_GENERATOR_TRILEMMA_KERNEL_BOUNDED_THEOREM_NOTE_2026-08-21.md",
            "docs/MINIMAL_AXIOMS_2026-06-29.md",
            "docs/audit/data/axiom_premise_nodes.json",
            "docs/ADMISSIBILITY_DIRAC_KAHLER_CLOSURE_AUDIT_TWO_BOUNDED_THEOREM_NOTE_2026-08-21.md",
            "scripts/admissibility_dirac_kahler_closure_audit_two_2026_08_21.py",
        )
        and PARENT_ARTIFACTS == (BLOCK170_NOTE, BLOCK170_RUNNER)
        and len(PARENT_ARTIFACT_BLOBS) == len(PARENT_ARTIFACTS) == 2
        and facts.main_head == claims["main_head"]
        and authority.fixed_authority
        and authority.parent_import_landed
        and authority.parent_pin_is_commit
        and authority.parent_ref_and_ancestry
        and parent_blobs_ok)

    ban = facts.banners
    conv = ban["convention"]
    gate_b = bool(
        # THE CONVENTION COLLISION, MEASURED on identical matrices.
        conv["pairs"] == (((4, 4, 0), (4, 0, 4)),
                          ((4, 0, 4), (4, 4, 0)),
                          ((0, 3, 0), (0, 0, 3)))
        and conv["landed_psd"] and conv["here_psd"]
        and conv["orders_differ"] == (not claims["lane_conventions_uniform"])
        # THE IMPOSED-OBJECT BANNER, as a measured object.
        and ban["imposed_objects"] == 9
        and ban["registered_objects"] == 0
        and ban["design_fork_arms"] == 2
        and all(
            ban["sites"][tag]["bench_is_landed"]
            and ban["sites"][tag]["T_phys"] == PHYS_T[tag]
            and ban["sites"][tag]["lx"] == L_X[tag]
            and ban["sites"][tag]["d_squared_entries"] == 0
            and ban["sites"][tag]["r_squared_one"]
            and ban["sites"][tag]["x_trivial"] == PHYS_T[tag]
            # THE COMMITTED-QUOTIENT ANCHORS
            and ban["sites"][tag]["herm_q_connection_free"]
            and ban["sites"][tag]["a_anti_hermitian"]
            and ban["sites"][tag]["a_carries_connection"]
            and ban["sites"][tag]["form_inertia"] == EXPECTED_REGION["bench"]
            and ban["sites"][tag]["dial_reproduces_committed"]
            # THE ALPHABET COUNT, with the closed form corrected
            and ban["sites"][tag]["free_shears"] == EXPECTED_ALPHABET[tag]
            and ban["sites"][tag]["alphabet_formula_matches"]
            and not ban["sites"][tag]["superseded_formula_matches"]
            # THE MACHINERY GATE, in the place where it is load-bearing
            and ban["sites"][tag]["lu_agrees_where_lu_terminates"]
            and all(ban["sites"][tag]["dialled_inverse_residual_zero"].values())
            for tag in TAGS)
        and len(TAGS) == 2
        and facts.exact_no_float
        and facts.source_floats == 0)

    tab = facts.table
    bench = tab[BENCH_TAG]
    gate_c = bool(
        len(BATTERY) == 10
        and bench["winners"] == claims["winning_set"]
        and bench["deep"] == EXPECTED_DEEP
        and tab["8x4"]["winners"] == EXPECTED_WINNERS
        and all(
            # W1: connection-blind BY THEOREM, SAME on all five dials
            set(tab[tag]["rows"]["W1"][sc]["leg_iii"].values()) == {"same"}
            for tag in TAGS for sc in ("SC", "RS"))
        and all(
            # W5: UNDEFINED at connection-off, SAME on the s_x dial
            tab[tag]["rows"]["W5"][sc]["leg_iii"]["conn_off"] == "undefined"
            and tab[tag]["rows"]["W5"][sc]["leg_iii"]["sx_dial"] == "same"
            for tag in TAGS for sc in ("SC", "RS"))
        and all(
            # W3 == W4 on the region, leg (i) MEASURED rather than asserted
            tab[tag]["rows"]["W3W4"]["corner_zero"]
            and tab[tag]["rows"]["W3W4"]["diagonal"]
            and tab[tag]["rows"]["W3W4"]["shear_free"]
            and tab[tag]["rows"]["W3W4"]["connection_free"]
            and is_pd(tab[tag]["rows"]["W3W4"]["inertia"])
            for tag in TAGS)
        # W8: NOT a state, and its leg-(iii) predicate is the WEAKER one
        and not bench["rows"]["W8"]["is_state"]
        and bench["rows"]["W8"]["real_diagonal"]
        and not bench["rows"]["W8"]["full_psd"]
        and bench["rows"]["W8"]["iii_partial"]
        # every RS winner is PD on its compressed block
        and all(tab[tag]["rows"][g]["RS"]["inertia"] == EXPECTED_RS_BLOCK[tag]
                for tag in TAGS for g in sorted(EXPECTED_WINNERS))
        # THE REGION DISCLOSURE: two of the four dials LEAVE the region, and
        # leg (i) survives at all four
        and bench["region"] == EXPECTED_REGION
        and all(bench["herm_at_dials"][k] == EXPECTED_HERM_Q[BENCH_TAG]
                for k in bench["herm_at_dials"])
        and all(bench["w9_at_dials"][k] == EXPECTED_RS_BLOCK[BENCH_TAG]
                for k in bench["w9_at_dials"])
        and facts.exact_no_float)

    con = facts.congruence
    gate_d = bool(
        con["generic_2x2_identity"]
        and all(
            con[tag]["congruence"]
            and con[tag]["w10_identity"]
            and con[tag]["a_anti_hermitian"]
            and con[tag]["nonsingular_residual"]
            and con[tag]["herm_q"][sp.Integer(1)] == EXPECTED_HERM_Q[tag]
            and con[tag]["herm_q"][sp.Integer(3)] == EXPECTED_HERM_Q[tag]
            and con[tag]["w9_inertia"] == EXPECTED_HERM_Q[tag]
            and con[tag]["w10_inertia"] == EXPECTED_HERM_Q[tag]
            # THE TWIN, at MATRIX level: the checker's STRONGER form
            and con[tag]["matrix_invariant_under_full_dial"]
            and con[tag]["twin_is_connection_off_control"]
            and con[tag]["profiles_differ"]
            for tag in TAGS)
        # THE SEPARATION, at the bench: W9 moves on BOTH holonomy dials
        and all(con[BENCH_TAG]["w9_moves"].values())
        and con[BENCH_TAG]["holo_separation"] != 0
        and (all(con[tag]["congruence"] and con[tag]["w10_identity"]
                 for tag in TAGS) == claims["congruence_theorem"])
        and (any(con[tag]["w2_moves"][k] for tag in TAGS
                 for k in con[tag]["w2_moves"]) == claims["twin_moves"])
        and facts.exact_no_float)

    sl = facts.slices
    record_sensitive = any(tab[tag]["rows"][g]["SC"]["legii"]
                           for tag in TAGS for g in GRAMS)
    gate_e = bool(
        all(
            sl[tag]["s1"]
            # S1 is an s_t = 0 FACT, not a region-pin fact alone
            and not sl[tag]["s1_with_st_free"]
            and sl[tag]["s2_shear_free"]
            and sl[tag]["s2_symbol_count"] == EXPECTED_S2_SYMBOLS[tag]
            and sl[tag]["corollary_exhibited"]
            and sl[tag]["no_normalization_leak"]
            and all(sl[tag]["grams_block_diagonal"][g] for g in GRAMS)
            and sl[tag]["sc_blind_count"] == sl[tag]["battery_count"] == 7
            for tag in TAGS)
        and record_sensitive == claims["slice_weights_record_sensitive"]
        and facts.exact_no_float)

    k = facts.kid
    gate_f = bool(
        k["cm_site"]["hermitian_idempotent"]
        and k["cm_site"]["orthogonal"]
        and k["cm_site"]["resolution_of_identity"]
        and k["cm_site"]["coarse_graining_nonvacuous"]
        and not k["cm_value"]["is_projector_partition"]
        and k["k1_site_symbolic"]
        # K1 IS CONTENT-FREE: it holds for an ARBITRARY matrix too
        and k["k1_site_content_free"]
        and all(
            k[tag]["k1_site_numeric"]
            and k[tag]["k1_value_defect"] != 0
            and k[tag]["k2_action"]
            # THE CHAIN-RULE construction is order-dependent, exact nonzero
            and k[tag]["chain_rule_defect"] != 0
            # THE ONE-SHOT JOINT is exactly order-free, exact zero
            and k[tag]["oneshot_defect"] == 0
            and k[tag]["oneshot_sums_to_one"]
            # THE SOLVE'S WITNESS reproduces its nonzero defect AND is mis-wired
            and k[tag]["solve_witness_defect"] != 0
            and k[tag]["same_slice_classes_orthogonal"]
            and k[tag]["solve_witness_mixes_wirings"]
            and k[tag]["k3"]
            and k[tag]["k3_min"] > 0
            and k[tag]["ionescu_tulcea_inputs"]
            # THE ERGODICITY RESIDUE, named rather than supplied
            and not k[tag]["ergodicity_supplied"]
            for tag in TAGS)
        and (any(k[tag]["solve_witness_is_a_joint"] for tag in TAGS)
             == claims["solve_witness_is_a_joint"])
        and (all(k[tag]["k1_value_holds"] for tag in TAGS)
             == claims["k1_value_alphabet_holds"])
        and (any(not k[tag]["oneshot_order_free"] for tag in TAGS)
             == claims["oneshot_order_dependent"])
        and facts.exact_no_float)

    cen = facts.census
    l2 = facts.l2
    census_tags = tuple(cen)
    zero_collisions = all(not cen[tag]["collisions_exist"]
                          for tag in census_tags)
    universal_null = all(
        l2[tag]["carriers"][mode]["uniform_everywhere"]
        for tag in l2 for mode in ("flat", "graded"))
    gate_g = bool(
        BENCH_TAG in census_tags
        and all(
            all(cen[tag][key] == value
                for key, value in EXPECTED_CENSUS.items())
            and cen[tag]["collisions_exist"]
            and cen[tag]["multisets"] == 10
            and cen[tag]["doubly_covered"] == 6
            and cen[tag]["separation_witness"] != 0
            and cen[tag]["all_sum_to_one"]
            and cen[tag]["all_strictly_positive"]
            and cen[tag]["checker_mismatches"] == 0
            for tag in census_tags)
        # LEMMA L2: x-homogeneity buys PERIOD 2, not uniformity
        and all(
            l2[tag]["carriers"][mode]["x_homogeneous"]
            and l2[tag]["carriers"][mode]["cells_measured"] == 14
            and not l2[tag]["carriers"][mode]["uniform_everywhere"]
            and l2[tag]["carriers"][mode]["rs_non_uniform"] == L2_NON_UNIFORM
            and l2[tag]["carriers"][mode]["rs_period_2"] == L2_NON_UNIFORM
            and l2[tag]["carriers"][mode]["candidate_is_null"]
            and all(l2[tag]["carriers"][mode]["weights"][(g, "RS")]["uniform"]
                    for g in L2_UNIFORM)
            and all(l2[tag]["carriers"][mode]["weights"][(g, "SC")]["uniform"]
                    for g in GRAMS)
            for tag in l2 for mode in ("flat", "graded"))
        # THE EXACT COUNTER-WITNESS that refutes the solve's sentence
        and l2[BENCH_TAG]["carriers"]["flat"]["weights"][("W6", "RS")][
            "profile"] == EXPECTED_L2_FLAT_W6
        # THE PROBE CARRIER, non-uniform and inside the positive region
        and all(l2[tag]["probe_carrier_non_uniform"]
                and l2[tag]["probe_carrier_in_region"]
                == EXPECTED_REGION["bench"]
                and l2[tag]["graded_carrier_in_region"]
                == EXPECTED_REGION["bench"]
                and l2[tag]["period_lattice"] == 2
                for tag in l2)
        and zero_collisions == claims["zero_collisions_reachable"]
        and universal_null == claims["null_fixture_universal"]
        and facts.exact_no_float)

    required = tuple(claims["required_scope_keys"])
    budget = DEEP_RUNTIME_BUDGET_SEC if facts.deep else RUNTIME_BUDGET_SEC
    gate_h = bool(
        # THE NOTE AT ITS FINAL PATH.  An unlanded draft fails HERE and only
        # here; the scope certificate is still computed from the declared draft
        # fallback so the supervisor can see every key before landing.
        facts.note_at_final_path
        and NOTE_PATH.name == FINAL_NOTE_NAME
        and set(facts.scope) == set(SCOPE_KEYS)
        and all(facts.scope[key] for key in required)
        and len(MUTATIONS) == 15
        and len(set(MUTATIONS)) == 15
        and set(MUTATION_GATE) == set(MUTATIONS)
        and set(MUTATION_GATE.values()) == set("ABCDEFGH")
        # THE N5 FENCE: a SINGLE-LINE literal, N5-prefixed, 9 to 12 lines
        and N5_FENCE.startswith("N5: ")
        and 9 <= N5_FENCE.count("\n") + 1 <= 12
        and all(N5_FENCE.count(f"\n{name}:") == 1
                for name in ("per_site", "per_mode", "per_block",
                             "lattice_wide", "per_scope", "RESULT",
                             "DECISION_CUT", "TOE"))
        and POOL_TWO_LEADS == 5
        and HANDOFF_ITEMS == 3
        and elapsed_ns <= budget * 1_000_000_000)

    return {"A": gate_a, "B": gate_b, "C": gate_c, "D": gate_d,
            "E": gate_e, "F": gate_f, "G": gate_g, "H": gate_h}


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--mutation", choices=MUTATIONS, default="")
    parser.add_argument(
        "--list-mutations", action="store_true",
        help="print the declared mutation names, one per line, and exit")
    parser.add_argument(
        "--deep", action="store_true",
        help="the pre-census and the L2 probe at BOTH extents and the W8 "
             "moment battery at both; the baseline runs a disclosed SAMPLE at "
             "the bench extent only, and the runtime budget is lengthened")
    arguments = parser.parse_args()
    if arguments.list_mutations:
        for name in MUTATIONS:
            print(name)
        return 0
    mutation = arguments.mutation
    started_ns = time.monotonic_ns()

    # Every measurement happens once, before any mutation flag is consulted, so
    # a mutation can only rewrite a CLAIM.  No gate can cascade into another
    # because no gate feeds a measurement.
    facts = measure(arguments.deep)
    elapsed_ns = time.monotonic_ns() - started_ns

    raw_gates = evaluate_gates(facts, build_claims(""), elapsed_ns)
    gate_values = dict(raw_gates)
    if mutation:
        target = MUTATION_GATE[mutation]
        gate_values = evaluate_gates(facts, build_claims(mutation), elapsed_ns)
        changed = {k for k in raw_gates if raw_gates[k] != gate_values[k]}
        if changed - {target} or gate_values[target]:
            raise AssertionError("mutation did not fail exactly its own gate")

    ban, tab = facts.banners, facts.table
    con, sl = facts.congruence, facts.slices
    k, cen, l2 = facts.kid, facts.census, facts.l2
    conv = ban["convention"]
    bench = tab[BENCH_TAG]

    print("MEASURED, before any gate is read:")
    print(f"  PARENT IMPORT: the Block 170 runner imported "
          f"{facts.authority.parent_import_landed}; PARENT_COMMIT "
          f"{PARENT_COMMIT} pins BOTH Block 170 artifacts")
    print(f"  THE NOTE: read at its FINAL PATH {facts.note_at_final_path} -- "
          f"when False this is an UNLANDED DRAFT reading the DECLARED FALLBACK "
          f"{DRAFT_NOTE_PATH.name}, gate H is EXPECTED to fail, and the three "
          f"gate-H mutations are UNTESTABLE until the note lands; gates A-G "
          f"are unaffected.  Scope keys satisfied: "
          f"{sum(1 for v in facts.scope.values() if v)} of "
          f"{len(facts.scope)}; unsatisfied "
          f"{tuple(key for key, value in facts.scope.items() if not value)}")
    print(f"  THE INERTIA CONVENTION, FIRST: the landed b163/b164 helper and "
          f"the landed Block 165 helper on IDENTICAL matrices {conv['pairs']} "
          f"-- each pair (b163/b164, this note); both call the region normal "
          f"form PSD ({conv['landed_psd']}, {conv['here_psd']}) and the tuple "
          f"ORDERS DIFFER {conv['orders_differ']}, so the literal string "
          f"(4,4,0) means PSD in Block 164's landed fence and FULLY HYPERBOLIC "
          f"here")
    print(f"  THE IMPOSED-OBJECT BANNER: {record(ban['imposed_objects'])} "
          f"objects built by this block, {record(ban['registered_objects'])} "
          f"registered, adopted or proposed; the DESIGN FORK has "
          f"{record(ban['design_fork_arms'])} arms and goes to the owner's bar "
          f"undecided -- {IMPOSED_OBJECTS}")
    for tag in TAGS:
        row = ban["sites"][tag]
        print(f"  THE BENCH at {tag} (T_phys = {record(row['T_phys'])}"
              f"{', THE BENCH' if tag == BENCH_TAG else ', DISCLOSED CROSS-CHECK'}"
              f"): rebuilt from the landed chain {row['bench_is_landed']}, "
              f"d^2 entries {record(row['d_squared_entries'])}, r^2 = 1 "
              f"{row['r_squared_one']}, x-trivial {record(row['x_trivial'])}; "
              f"[rQ]_(S,S) at the probe carrier {tri(row['form_inertia'])}; "
              f"herm(Q) connection-free {row['herm_q_connection_free']}, A "
              f"anti-Hermitian {row['a_anti_hermitian']} and carrying both "
              f"connection symbols {row['a_carries_connection']}; THE RECORD "
              f"ALPHABET {record(row['free_shears'])} free shears -- closed "
              f"form L_x (T_phys - 2) = {record(row['alphabet_closed_form'])} "
              f"MATCHES {row['alphabet_formula_matches']}, the SUPERSEDED form "
              f"2 L_x (T_phys - 2) = "
              f"{record(row['alphabet_superseded_form'])} matches "
              f"{row['superseded_formula_matches']} -- THE SOLVE'S ARITHMETIC "
              f"ERROR, DISCLOSED; THE MACHINERY GATE: DomainMatrix agrees with "
              f"the landed LU route entry for entry WHERE LU TERMINATES "
              f"{row['lu_agrees_where_lu_terminates']}, and on the DIALLED "
              f"actions -- where the landed LU route DID NOT TERMINATE at 8x4 "
              f"after 7.5 minutes, disclosed -- the residual Q Q^-1 - 1 is "
              f"exactly zero {row['dialled_inverse_residual_zero']}")
    for tag in TAGS:
        row = tab[tag]
        print(f"  THE TRILEMMA TABLE at {tag}: battery {record(row['battery'])} "
              f"members; WINNERS at RS scope {sorted(row['winners'])}; DEEP "
              f"(moved by a record at the FARTHEST free level) "
              f"{sorted(row['deep'])}")
        for g in GRAMS:
            cell = row["rows"][g]
            print(f"    {g:3s} SC i={'P' if cell['SC']['legi'] else 'F'}"
                  f" ii={'P' if cell['SC']['legii'] else 'F'}"
                  f" iii={'P' if cell['SC']['legiii'] else 'F'}"
                  f" | RS i={'P' if cell['RS']['legi'] else 'F'}"
                  f" ii={'P' if cell['RS']['legii'] else 'F'}"
                  f" iii={'P' if cell['RS']['legiii'] else 'F'}"
                  f"  RS inertia="
                  f"{tri(cell['RS']['inertia']) if cell['RS']['inertia'] else 'n/a'}"
                  f"  movers={cell['RS']['movers']}  dials={cell['RS']['leg_iii']}")
        w34 = row["rows"]["W3W4"]
        print(f"    W3 == W4 ON THE REGION exactly: corner C = s_t.C_1 vanishes "
              f"{w34['corner_zero']}, B diagonal {w34['diagonal']}, D(c,.) "
              f"shear-free {w34['shear_free']} and connection-free "
              f"{w34['connection_free']}; leg (i) MEASURED (not asserted) "
              f"{tri(w34['inertia'])}")
        print(f"    THE DIALS AND THE REGION, DISCLOSED: [rQ]_(S,S) reads "
              + " ".join(f"{key}:{tri(value)}"
                         for key, value in row["region"].items())
              + f" -- TWO OF THE FOUR leg-(iii) dials LEAVE THE POSITIVE "
              f"REGION; herm(Q) stays "
              + " ".join(f"{key}:{tri(value)}"
                         for key, value in row["herm_at_dials"].items())
              + " and the W9 RS block stays "
              + " ".join(f"{key}:{tri(value)}"
                         for key, value in row["w9_at_dials"].items())
              + f", so leg (i) survives at all four and the verdict rests on "
              f"the in-region dials {row['in_region_dials']}")
    if "W8" in bench["rows"]:
        w8 = bench["rows"]["W8"]
        print(f"  W8, THE MOMENT-MATRIX WEIGHT at {BENCH_TAG}: it is a STATE "
              f"{w8['is_state']} (G = Q^-1 is not Hermitian, so the matrix is "
              f"not Hermitian and W8 is NOT a state); real positive diagonal "
              f"{w8['real_diagonal']} so the ratio still normalizes; the FULL "
              f"matrix's Hermitian part is PSD {w8['full_psd']}; herm-part "
              f"connected "
              f"{tri(w8['cells'][('bench', 'connected')]['herm_inertia'])} and "
              f"full {tri(w8['cells'][('bench', 'full')]['herm_inertia'])}; "
              f"and its leg-(iii) test is the WEAKER PARTIAL predicate "
              f"(conn_off and s_x only) {w8['iii_partial']} -- NAMED SEPARATELY "
              f"and never scored as the table's iii")
    for tag in TAGS:
        row = con[tag]
        print(f"  THE POSITIVITY CONGRUENCE THEOREM at {tag}: "
              f"herm(Q^-1) == Q^-1 herm(Q) Q^-dag entry for entry "
              f"{row['congruence']} (and on a GENERIC symbolic complex 2x2 "
              f"{con['generic_2x2_identity']}); Q^dag herm(Q)^-1 Q == herm(Q) "
              f"+ A^dag herm(Q)^-1 A {row['w10_identity']} with A^dag = -A "
              f"{row['a_anti_hermitian']}; NONSINGULARITY IS NOT AN EXTRA "
              f"HYPOTHESIS -- herm(Q) > 0 forces it, and the residual "
              f"Q Q^-1 - 1 is exactly zero {row['nonsingular_residual']}; "
              f"SYLVESTER then gives herm(Q) at m=1 {tri(row['herm_q'][sp.Integer(1)])} "
              f"and m=3 {tri(row['herm_q'][sp.Integer(3)])}, herm(Q^-1) "
              f"{tri(row['w9_inertia'])}, Q^dag herm(Q)^-1 Q "
              f"{tri(row['w10_inertia'])} -- a CENSUS in m and the moduli, not "
              f"a theorem in them; THE ANTI-SHIM SEPARATION INSIDE ONE FORMULA: "
              f"W9 moves under the holonomy dials {row['w9_moves']} while the "
              f"twin herm(Q)^-1 moves {row['w2_moves']} -- and STRONGER, "
              f"herm(Q) is MATRIX-INVARIANT under the full complex dial "
              f"{row['matrix_invariant_under_full_dial']}, so the separation "
              f"is against that whole invariant subalgebra; the twin IS the "
              f"connection-off covariance entrywise "
              f"{row['twin_is_connection_off_control']} and the two profiles "
              f"differ {row['profiles_differ']}")
    for tag in TAGS:
        row = sl[tag]
        print(f"  S1 / S2 AT {tag}: slice c is a DIRECT SUMMAND of Q at "
              f"s_t = 0 {row['s1']}, and with s_t LEFT FREE that fails "
              f"{row['s1_with_st_free']} -- so S1 is an s_t = 0 fact and NOT a "
              f"region-pin fact alone; Q[c,c] carries NO free-shear symbol "
              f"{row['s2_shear_free']} over {record(row['s2_symbol_count'])} "
              f"symbols {row['s2_symbols']}; COROLLARY exhibited "
              f"herm(Q^-1)_cc == herm((Q_cc)^-1) {row['corollary_exhibited']}; "
              f"NO NORMALIZATION LEAK -- every gram is itself block-diagonal "
              f"w.r.t. slice c {row['grams_block_diagonal']}, so numerator and "
              f"denominator are functionals of Q_cc alone; RECORD-BLIND BY "
              f"THEOREM at SC scope for {record(row['sc_blind_count'])} of "
              f"{record(row['battery_count'])} {row['sc_blind']}")
    print(f"  THE CLASS MAPS: CM-SITE is Hermitian and idempotent "
          f"{k['cm_site']['hermitian_idempotent']}, mutually orthogonal "
          f"{k['cm_site']['orthogonal']} and a RESOLUTION OF THE IDENTITY "
          f"{k['cm_site']['resolution_of_identity']} with |A| = "
          f"{record(k['cm_site']['alphabet_size'])} >= 3 so the "
          f"coarse-graining leg is not vacuous; CM-VALUE is a projector "
          f"partition {k['cm_value']['is_projector_partition']} -- DECLARED "
          f"ABSENT, not measured absent, refutable by exhibiting a landed "
          f"operator with {k['cm_value']['classes']} as spectrum")
    print(f"  K1 (site alphabet) is an identity in a symbolic HERMITIAN G "
          f"{k['k1_site_symbolic']} AND in an ARBITRARY symbolic G "
          f"{k['k1_site_content_free']} -- so it is TRUE BUT CONTENT-FREE: at "
          f"the diagonal site projectors it says the diagonal entries sum to "
          f"the trace, and the forward-normalization hypothesis is discharged "
          f"by the DEFINITION of the ratio, not by this identity")
    for tag in TAGS:
        row = k[tag]
        nk, dk = sp.fraction(row["k1_value_defect"])
        print(f"  THE K-IDENTITIES at {tag}: K1 (site) re-verified on the "
              f"candidate over every declared trail {row['k1_site_numeric']}; "
              f"K1 (VALUE alphabet) defect is an EXACT NONZERO rational with a "
              f"{record(len(str(nk)))}-digit numerator over a "
              f"{record(len(str(dk)))}-digit denominator, the four ratios "
              f"sitting near 1 so the sum sits near |A_v| = 4 -- STRUCTURAL, "
              f"not small; K2 AT THE ACTION LEVEL holds with free symbols "
              f"surviving {row['k2_action']}; THE CHAIN-RULE construction over "
              f"two DISTINCT free time levels, records as the DECLARED "
              f"disconnection pin, class read AT THE SLOT BEING FILLED, is "
              f"ORDER-DEPENDENT by the exact nonzero rational "
              f"{record(row['chain_rule_defect'])} != 0; THE ONE-SHOT GIBBS "
              f"JOINT over the same two link slots on the disclosed 2-value "
              f"sub-alphabet {row['oneshot_alphabet']} is EXACTLY "
              f"ORDER-INDEPENDENT, defect {record(row['oneshot_defect'])}, and "
              f"sums to 1 {row['oneshot_sums_to_one']}; THE SOLVE'S ORIGINAL "
              f"WITNESS reproduces its nonzero defect "
              f"{record(row['solve_witness_defect'])} != 0 BUT IS MIS-WIRED -- "
              f"the two same-slice class events are the mutually ORTHOGONAL "
              f"Pi_0, Pi_1 ({row['same_slice_classes_orthogonal']}) so their "
              f"product of conditionals is NOT a joint of the declared class "
              f"map, and it mixes CM-VALUE records with a CM-SITE index "
              f"({row['solve_witness_mixes_wirings']}); K3 holds "
              f"{row['k3']} with smallest class weight "
              f"{record(row['k3_min'])}; IONESCU-TULCEA inputs K1 + K3 present "
              f"{row['ionescu_tulcea_inputs']} so the half-infinite process is "
              f"built FORWARD with NO COMPLETED FUTURE, while ERGODICITY is "
              f"supplied {row['ergodicity_supplied']} -- the open residue, "
              f"named")
    for tag in cen:
        row = cen[tag]
        print(f"  THE PRE-CENSUS at {tag}: {record(row['trails'])} trails; "
              f"{record(row['distinct_weights'])} of {record(row['trails'])} "
              f"distinct WEIGHT profiles; "
              f"{record(row['distinct_frequencies'])} of "
              f"{record(row['trails'])} distinct FREQUENCY profiles; "
              f"{record(row['frequencies_carrying_two_weights'])} frequency "
              f"profiles carry TWO weight profiles and "
              f"{record(row['weights_carrying_two_frequencies'])} weight "
              f"profiles carry two frequency profiles; COLLISIONS EXIST "
              f"{row['collisions_exist']}, and the count is FORCED "
              f"combinatorially -- the frequency profile of a length-2 trail "
              f"is its MULTISET, {record(row['multisets'])} multisets of which "
              f"{record(row['doubly_covered'])} are doubly covered; separation "
              f"witness {record(row['separation_witness'])} != 0; every "
              f"profile sums to 1 {row['all_sum_to_one']} and is strictly "
              f"positive {row['all_strictly_positive']}; the DISJOINT CHECKER "
              f"rebuilt {record(row['checker_rows_rebuilt'])} of 32 rows by an "
              f"independent route with {record(row['checker_mismatches'])} "
              f"mismatches")
    for tag in l2:
        row = l2[tag]
        for mode in ("flat", "graded"):
            cell = row["carriers"][mode]
            print(f"  LEMMA L2 at {tag}, carrier {mode}: x-homogeneous "
                  f"{cell['x_homogeneous']}; all "
                  f"{record(cell['cells_measured'])} (weight, scope) cells "
                  f"measured; UNIFORM EVERYWHERE {cell['uniform_everywhere']} "
                  f"-- the solve's SECOND NULL FIXTURE sentence REFUTED AS "
                  f"STATED; NON-UNIFORM at RS scope {cell['rs_non_uniform']}, "
                  f"and each of those is exactly x-PERIOD-2 "
                  f"{cell['rs_period_2']}; the CANDIDATE W9 is itself null "
                  f"there {cell['candidate_is_null']}; W6 RS profile "
                  f"{cell['weights'][('W6', 'RS')]['profile']}")
        print(f"  THE PROBE CARRIER at {tag}: non-uniform "
              f"{row['probe_carrier_non_uniform']} and INSIDE the positive "
              f"region {tri(row['probe_carrier_in_region'])} (the landed "
              f"graded carrier: {tri(row['graded_carrier_in_region'])}); the "
              f"period lattice is {record(row['period_lattice'])}")
    print(f"  SAMPLING: --deep {facts.deep}; the pre-census, the L2 probe and "
          f"the W8 battery run at {tuple(cen)} in this pass and at both "
          f"extents under --deep")
    print(f"  EXACTNESS: no float in any measured object "
          f"{facts.exact_no_float} over {record(len(NUMERALS))} numerals, and "
          f"{record(facts.source_floats)} float literals in this file's own "
          f"AST")
    print()

    checks = Checks()
    checks.check(
        "A-authority",
        "main plus TWO parent artifacts are content-bound: Block 170's note and runner, which are BOTH the stack parent this block's branch is cut from AND the content parent -- this runner IMPORTS the Block 170 runner and every committed convention below it (b169 -> b168 -> b167 -> b166 -> b165 -> b164 -> b163 -> ... -> b105) is reached through Block 170's own import chain, which Block 170's gate A pins rather than this one duplicating it; the gate additionally requires that the Block 170 runner ACTUALLY IMPORTED, and the stale pin is the Block 169 tip, verified to carry NEITHER Block 170 artifact",
        gate_values["A"])
